<template><div class="player" v-if="programme"><header><div><q-btn flat round icon="arrow_back" to="/teacher/quizzes"/><b>Galena.lk · {{ programme.title }}</b></div><div><span class="timer" :class="{warning:remaining<=30&&remaining>0}">⏱ {{ timerText }}</span><strong>{{ programme.is_finished?'FINAL RESULTS':`QUESTION ${index+1} OF ${programme.questions.length}` }}</strong></div></header><main v-if="programme.is_finished" class="finish"><div><q-icon name="emoji_events"/><h1>Quiz Complete!</h1><p>Final results are in.</p><div class="winner">🏆 {{ winners }} — {{ highest }} points</div></div></main><main v-else><section class="qa"><div class="tag">{{ question.category }}</div><h1>{{ question.question_text }}</h1><img v-if="question.image_path" :src="imageUrl(question.image_path)" class="q-image"/><div class="answers" :class="{five:question.answers.length===5}"><div v-for="(answer,i) in question.answers" :key="answer.id" class="answer" :class="{correct:programme.answer_revealed&&answer.is_correct}"><span>{{ String.fromCharCode(65+i) }}</span><div><img v-if="answer.image_path" :src="imageUrl(answer.image_path)"/><b>{{ answer.answer_text }}</b></div></div></div></section><aside><h2>LIVE SCOREBOARD</h2><div v-for="(team,i) in programme.teams" :key="team.id" class="team"><i :style="{background:colors[i%colors.length]}"></i><b>{{ team.name }}</b><strong :style="{color:colors[i%colors.length]}">{{ team.score }}</strong></div></aside></main><footer><template v-if="!programme.is_finished"><q-btn no-caps icon="arrow_back" label="Previous" :disable="index===0" @click="previous"/><q-btn no-caps icon-right="arrow_forward" label="Next" @click="next"/><q-btn no-caps :icon="programme.answer_revealed?'visibility_off':'visibility'" :label="programme.answer_revealed?'Hide Answer':'Show Answer'" class="gold" @click="reveal"/></template><q-btn no-caps icon="scoreboard" label="Update marks" color="primary" @click="scoreDialog=true"/><q-btn v-if="programme.is_finished" no-caps icon="replay" label="Start again" @click="restart"/><q-btn no-caps icon="settings" :to="`/teacher/quizzes/${programme.id}/edit`"/></footer><q-dialog v-model="scoreDialog"><q-card class="score-dialog"><q-card-section><h2>Update Marks</h2><p>Scores are saved to the database.</p><div class="score-controls"><div v-for="team in programme.teams" :key="team.id"><b>{{ team.name }}: {{ team.score }}</b><span><q-btn unelevated label="−1" color="negative" @click="adjust(team,-1)"/><q-btn unelevated label="+1" color="primary" @click="adjust(team,1)"/><q-btn unelevated label="+10" color="primary" @click="adjust(team,10)"/></span></div></div></q-card-section><q-card-actions align="right"><q-btn flat label="Done" v-close-popup/></q-card-actions></q-card></q-dialog></div><div v-else class="loading"><q-spinner size="45px" color="primary"/></div></template>
<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import { useQuizStore } from 'src/stores/quiz-store';
const route=useRoute(),quiz=useQuizStore(),programme=ref(null),scoreDialog=ref(false),remaining=ref(0),timerId=ref(null),colors=['#1677ff','#20c5b5','#f15a5a','#8b5cf6','#f59e0b','#10b981']
const index=computed(()=>programme.value?.current_question_index||0),question=computed(()=>programme.value?.questions[index.value]),highest=computed(()=>Math.max(...programme.value.teams.map(t=>t.score))),winners=computed(()=>programme.value.teams.filter(t=>t.score===highest.value).map(t=>t.name).join(' & ')),timerText=computed(()=>`${String(Math.floor(remaining.value/60)).padStart(2,'0')}:${String(remaining.value%60).padStart(2,'0')}`)
const apiRoot=(process.env.BACKEND_URL?.trim().replace(/\/v1\/api\/?$/,'')||(location.hostname==='localhost'?'http://localhost:8080':'https://api.galena.lk')); const imageUrl=p=>`${apiRoot}${p}`
const stop=()=>{clearInterval(timerId.value);timerId.value=null}; const resetTimer=(start=false)=>{stop();remaining.value=question.value?.time_seconds||120;if(start)timerId.value=setInterval(()=>{if(remaining.value>0)remaining.value--;else stop()},1000)}
const persist=()=>quiz.saveSession(programme.value.id,{current_question_index:index.value,answer_revealed:programme.value.answer_revealed,is_finished:programme.value.is_finished,teams:programme.value.teams}).catch(console.error)
const next=()=>{if(index.value===programme.value.questions.length-1){programme.value.is_finished=true;stop()}else{programme.value.current_question_index++;programme.value.answer_revealed=false;resetTimer(true)}persist()}; const previous=()=>{if(index.value>0){programme.value.current_question_index--;programme.value.answer_revealed=false;resetTimer(true);persist()}}; const reveal=()=>{programme.value.answer_revealed=!programme.value.answer_revealed;persist()}; const adjust=(team,n)=>{team.score=Math.max(0,team.score+n);persist()}; const restart=()=>{programme.value.is_finished=false;programme.value.current_question_index=0;programme.value.answer_revealed=false;programme.value.teams.forEach(t=>t.score=0);resetTimer(true);persist()}
onMounted(async()=>{programme.value=await quiz.get(route.params.id);resetTimer(true)});onBeforeUnmount(stop)
</script>
<style scoped>
.player{width:100%;height:100vh;min-height:100vh;overflow:hidden;background:#edf4ff;color:#10233f}.player>header{position:fixed;z-index:6;inset:0 0 auto 0;width:100%;height:64px;padding:8px 3vw;display:flex;align-items:center;justify-content:space-between;color:#10233f;background:rgba(237,244,255,.94);border-bottom:1px solid #d7e4f5;backdrop-filter:blur(10px)}.player>header>div{display:flex;align-items:center;gap:12px}.player>header>div:last-child{gap:24px}.timer{min-width:110px;color:#c98800;font-size:25px;font-weight:900}.warning{color:#e04747;animation:pulse .8s infinite}@keyframes pulse{50%{opacity:.45}}.player>main{width:100%;height:100vh;display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,340px);gap:30px;padding:78px 3.5vw 78px;overflow:hidden}.qa{min-width:0;min-height:0;display:flex;flex-direction:column;justify-content:center;overflow:hidden}.tag{width:max-content;padding:6px 14px;color:#fff;background:#071b3b;border-radius:20px;font-weight:800}.qa h1{max-width:100%;margin:10px 0 12px;font-size:clamp(24px,3vw,44px);line-height:1.08;overflow-wrap:anywhere}.q-image{max-width:100%;max-height:20vh;object-fit:contain;object-position:left;margin-bottom:10px}.answers{min-height:0;display:grid;grid-template-columns:1fr 1fr;gap:11px}.answers.five{grid-template-columns:repeat(3,1fr)}.answer{min-width:0;min-height:72px;padding:10px;display:flex;align-items:center;gap:10px;background:#fff;border:2px solid #d8e6f8;border-radius:15px;font-size:clamp(14px,1.35vw,19px)}.answer>span{width:42px;height:42px;display:grid;place-items:center;flex:none;color:#fff;background:#1677ff;border-radius:10px;font-size:19px;font-weight:850}.answer>div{min-width:0;display:grid;gap:3px;overflow-wrap:anywhere}.answer img{max-width:100%;max-height:11vh;object-fit:contain}.answer.correct{border-color:#ffc94a;background:#fff9e6}.answer.correct>span{color:#071b3b;background:#ffc94a}.player aside{min-width:0;max-height:calc(100vh - 156px);align-self:center;padding:18px 15px;overflow:auto;background:#fff;border-radius:20px;box-shadow:0 8px 24px #14376d12}.player aside h2{margin:4px 0 14px;text-align:center;font-size:1.15rem}.team{margin:8px 0;padding:9px 11px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:8px;border:2px solid #dbe8f8;border-radius:13px}.team i{width:22px;height:22px;border-radius:6px}.team b{overflow-wrap:anywhere}.team strong{font-size:30px}.player>footer{position:fixed;z-index:7;right:18px;bottom:14px;display:flex;gap:7px}.player>footer .q-btn{color:#fff;background:#071b3b;border-radius:11px}.gold{color:#071b3b!important;background:#ffc94a!important}.finish{display:grid!important;place-items:center;grid-template-columns:1fr!important;text-align:center}.finish .q-icon{color:#ffc94a;font-size:80px}.finish h1{font-size:55px;margin:5px}.finish p{font-size:22px;color:#687b99}.winner{padding:20px 38px;background:#ffc94a;border-radius:17px;font-size:28px;font-weight:900}.score-dialog{min-width:min(650px,92vw);padding:12px;border-radius:20px}.score-dialog h2{margin-bottom:0}.score-dialog p{color:#7a899f}.score-controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.score-controls>div{padding:15px;display:grid;gap:12px;background:#edf4ff;border-radius:13px}.score-controls span{display:flex;gap:7px}.loading{min-height:100vh;display:grid;place-items:center}@media(max-width:900px){.player{height:auto;min-height:100vh;overflow:auto}.player>main{grid-template-columns:1fr;height:auto;min-height:100vh;overflow:auto}.answers,.answers.five{grid-template-columns:1fr}.player>footer{left:8px;right:8px;overflow:auto}.player>header b{display:none}.player>header>div:last-child{gap:8px}.player>header strong{font-size:.7rem}}
</style>
